import json
import collections

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find separator: a row or column with uniform values
    sep_col = None
    for j in range(w):
        if len(set(grid[i][j] for i in range(h))) == 1 and w - j - 1 > 0:
            sep_col = j
            break

    sep_row = None
    if sep_col is None:
        for i in range(h):
            if len(set(grid[i])) == 1 and len(grid) - i - 1 > 0:
                sep_row = i
                break

    # Count all values to find background
    all_vals = collections.Counter(cell for row in grid for cell in row)
    bg = all_vals.most_common(1)[0][0]

    if sep_col is not None:
        # Vertical split: compare left with right (skip separator)
        return [[3 if grid[r][c] == grid[r][c + sep_col + 1] else bg for c in range(sep_col)] for r in range(h)]
    elif sep_row is not None:
        # Horizontal split: compare top with bottom (skip separator)
        return [[3 if grid[r][c] == grid[r + sep_row + 1][c] else bg for c in range(w)] for r in range(sep_row)]
    else:
        return grid

